def executable_tokens(code):
    """Compare executable tokens, retaining indentation and all literal content."""
    return [(t.type,t.string) for t in tokenize.generate_tokens(io.StringIO(code).readline)
            if t.type not in (tokenize.COMMENT,tokenize.NL,tokenize.ENCODING)]

def annotate(code, detailed=False):
    if not code.strip(): return code
    dedented=textwrap.dedent(code)
    try: tree=ast.parse(dedented)
    except SyntaxError: return code
    # Only insert before actual statement starts, never into strings or continued expressions.
    starts={n.lineno for n in ast.walk(tree) if isinstance(n,ast.stmt)}
    lines=code.rstrip().splitlines(); out=[]
    for i,line in enumerate(lines,1):
        stripped=line.lstrip(); message=None
        if i in starts:
            if stripped.startswith('def '):
                name=stripped[4:].split('(')[0];message=METHODS.get(name)
                if i<len(lines) and lines[i].strip()=='pass':message='나중에 채울 메서드입니다. 지금은 pass로 빈 자리를 둡니다.'
            elif stripped.startswith('class '):
                cls=stripped[6:].split('(')[0].rstrip(':')
                message={'Terrain':'지형 한 칸: 그림·위치와 소속 그룹을 준비합니다.', 'Explorer':'탐사원: 입력·이동·점프와 상태를 관리합니다.', 'Expedition':'탐사 규칙: 점수·시간·충돌 결과와 진행 상태를 관리합니다.', 'Mission':'전투 규칙: 점수·편대·생명에 따른 진행 상태를 관리합니다.', 'Scout':'탐사선: 좌우 이동과 아군 발사를 담당합니다.', 'Raider':'적 한 기: 이동·발사와 시작 위치를 관리합니다.', 'Robot':'로봇 한 대: 이동·피격·재부팅 상태를 관리합니다.', 'Pulse':'펄스 한 발: 방향과 사거리로 이동/제거를 정합니다.', 'ScoutPulse':'아군 탄환 한 발: 위로 이동합니다.', 'RaiderPulse':'적 탄환 한 발: 아래로 이동합니다.', 'SignalSource':'신호 장치: 제자리에서 회전하는 표시물입니다.', 'Crystal':'신호 결정: 떨어져 이동하는 회수 대상입니다.', 'Gate':'이동문: 색 채널과 위치·애니메이션을 보관합니다.'}.get(cls, '객체의 동작을 정의하는 설계도입니다.')
            elif 'pygame.sprite.Group(' in stripped:
                name=stripped.split('=')[0].strip()
                message={'tiles':'화면에 그릴 타일 전체입니다.', 'all_tiles':'화면에 그릴 지형 전체입니다.', 'platforms':'착지 검사에 사용할 발판만 담습니다.', 'hazards':'위험 접촉을 검사할 타일만 담습니다.', 'explorers':'탐사원을 갱신하고 그릴 그룹입니다.', 'scouts':'아군 탐사선을 담습니다.', 'raiders':'현재 편대의 적들을 담습니다.', 'scout_pulses':'현재 아군 탄환을 담아 이동·충돌·개수를 관리합니다.', 'raider_pulses':'현재 적 탄환을 담아 이동·충돌·개수를 관리합니다.', 'robots':'현재 로봇을 갱신하고 충돌 검사할 그룹입니다.', 'pulses':'화면에 남아 있는 펄스들을 담습니다.', 'crystals':'아직 회수되지 않은 신호 결정들을 담습니다.', 'gates':'서로 연결할 이동문들을 담습니다.', 'sources':'회전하는 신호 장치들을 담습니다.'}.get(name, '같은 역할의 객체를 함께 관리할 빈 그룹입니다.')
            elif detailed:
                message=next((short for pattern,short,_ in CONCEPTS if re.search(pattern,stripped)),None)
            elif any(re.search(pattern,stripped) for pattern in [r'import pygame',r'pygame.init\(',r'display.set_mode',r'event.get\(',r'while running:',r'for row, cells',r'level_map =',r'if key not in image_cache',r'self.position \+=',r'self.grounded = True',r'self.state =',r'portal_remaining = 0.4',r'pygame.sprite.Group\(']):
                message=next((short for pattern,short,_ in CONCEPTS if re.search(pattern,stripped)),None)
        if message:
            indent=line[:len(line)-len(stripped)]
            if not out or out[-1].strip()!='# '+message:out.append(indent+'# '+message)
        out.append(line)
    result='\n'.join(out)+'\n'
    assert executable_tokens(result)==executable_tokens(code.rstrip()+'\n')
    return result

def teaching_block(code):
    selected=[]
    for pattern,short,long in CONCEPTS:
        if re.search(pattern,code,re.M):selected.append((short,long))
    prose=''
    if selected:
        prose='**왜 이렇게 쓰나요 — 이 편집을 읽는 순서**\n\n'
        for short,long in selected:prose+=f'- **{short}** {long}\n\n'
    return prose+'```python\n'+annotate(code,True).rstrip()+'\n```\n'
